function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // volcano
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 - 50, H/2 + 100);
  ctx.lineTo(W/2 + 50, H/2 + 100);
  ctx.closePath();
  ctx.stroke();

  // lightning
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 30 + 10 * Math.cos(t), H/2 - 20 + 10 * Math.sin(t));
  ctx.lineTo(W/2 + 30 + 10 * Math.cos(t), H/2 - 20 + 10 * Math.sin(t));
  ctx.lineTo(W/2, H/2 - 50 + 20 * Math.sin(t));
  ctx.stroke();

  // electric sparks
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(t + i) * 20, H/2 - 50 + Math.sin(t + i) * 20, 2, 0, 2 * Math.PI);
    ctx.fill();
  }

  ctx.restore();
}
